package com.bank.streak;

import java.util.logging.Logger;

// Reports the longest achievable uniform flag streak for National Bank of India.
public class StreakOptimizer {
    private static final Logger log = Logger.getLogger(StreakOptimizer.class.getName());

    // Longest substring uniform after <= k replacements. O(n), O(26).
    public int longestUniformStreak(String flags, int k) {
        if (flags == null) {
            throw new IllegalArgumentException("flags must not be null");
        }
        if (k < 0) {
            throw new IllegalArgumentException("k must be >= 0");
        }
        int[] count = new int[26];     // frequency of each uppercase flag
        int left = 0;
        int maxFreq = 0;               // high-water mark, never decreases
        int best = 0;
        for (int right = 0; right < flags.length(); right++) {
            int idx = flags.charAt(right) - 'A';
            count[idx]++;
            maxFreq = Math.max(maxFreq, count[idx]);     // track most frequent
            // Replacements needed = windowSize - maxFreq. Too many? shrink.
            if ((right - left + 1) - maxFreq > k) {
                count[flags.charAt(left) - 'A']--;
                left++;
            }
            best = Math.max(best, right - left + 1);      // window never shrinks below best
        }
        final int result = best;
        log.info(() -> "Longest uniform streak = " + result);
        return best;
    }
}
