package com.bank.streak;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: longest achievable uniform flag streak.
public class StreakOptimizerDemo {
    private static final Logger log = Logger.getLogger(StreakOptimizerDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        StreakOptimizer optimizer = new StreakOptimizer();

        log.info(() -> "Streak = " + optimizer.longestUniformStreak("ABAB", 2));  // 4
        log.info(() -> "Streak = " + optimizer.longestUniformStreak("AABABBA", 1)); // 4
        log.info(() -> "Streak = " + optimizer.longestUniformStreak("AABABBA", 0)); // 2
    }
}
